const EXPLORE_KEY='fractured-constellation-exploration-v1';
let explorationSequence=0;const minimapColors={};
function emptyExploration(){return Object.fromEntries(Object.entries(MAP_GRIDS).map(([id,m])=>[id,'0'.repeat(Math.ceil(m.w/m.cell)*Math.ceil(m.h/m.cell))]))}
function cleanExploration(value){const empty=emptyExploration();for(const id of Object.keys(empty))if(typeof value?.[id]==='string'&&value[id].length===empty[id].length&&/^[01]+$/.test(value[id]))empty[id]=value[id];return empty}
function mergeExploration(...values){const merged=emptyExploration();for(const value of values){const valid=cleanExploration(value);for(const id of Object.keys(merged))merged[id]=Array.from(merged[id],(v,i)=>v==='1'||valid[id][i]==='1'?'1':'0').join('')}return merged}
function persistExploration(){if(state.devTesting||!checkpoint||((checkpoint.explorationRun||'legacy')!==state.explorationRun))return;try{localStorage.setItem(EXPLORE_KEY,JSON.stringify({schema:1,run:state.explorationRun,maps:state.exploration}))}catch(_){}}
function revealMap(id,x,y){const m=MAP_GRIDS[id];if(!m||!Number.isFinite(x)||!Number.isFinite(y))return;state.exploration ||=emptyExploration();state.explorationLast ||= {};const last=state.explorationLast[id];if(last&&Math.hypot(x-last.x,y-last.y)<m.cell/2)return;state.explorationLast[id]={x,y};const cols=Math.ceil(m.w/m.cell),rows=Math.ceil(m.h/m.cell),cells=Array.from(state.exploration[id]||emptyExploration()[id]);let changed=false;for(let gy=Math.max(0,Math.floor((y-m.radius)/m.cell));gy<=Math.min(rows-1,Math.floor((y+m.radius)/m.cell));gy++)for(let gx=Math.max(0,Math.floor((x-m.radius)/m.cell));gx<=Math.min(cols-1,Math.floor((x+m.radius)/m.cell));gx++){if(Math.hypot((gx+.5)*m.cell-x,(gy+.5)*m.cell-y)>m.radius)continue;const index=gy*cols+gx;if(cells[index]!=='1'){cells[index]='1';changed=true}}if(changed){state.exploration[id]=cells.join('');persistExploration()}}
function exploredAt(id,x,y){const m=MAP_GRIDS[id];if(!m||x<0||y<0||x>=m.w||y>=m.h)return false;const cols=Math.ceil(m.w/m.cell);return state.exploration?.[id]?.[Math.floor(y/m.cell)*cols+Math.floor(x/m.cell)]==='1'}
function minimapColor(id,x,y){if(id==='world')return TERRAIN_COLORS[worldTerrain(x,y)][0];if(BELL_BUILDINGS.some(b=>x>=b.x&&x<=b.x+b.w&&y>=b.y&&y<=b.y+b.h))return '#d5bd89';if(BELL_HOMES.some(b=>x>=b.x&&x<=b.x+b.w&&y>=b.y&&y<=b.y+b.h))return '#96856e';if((x>=390&&x<=442)||(y>=181&&y<=234)||(y>=317&&y<=363)||(y>=462&&y<=502))return '#b6a78b';return '#777c64'}
function drawExplorationMap(id,p){const m=MAP_GRIDS[id];revealMap(id,p.x,p.y);const x=412,y=14,w=86,h=49,cols=Math.ceil(m.w/m.cell),rows=Math.ceil(m.h/m.cell);rect(406,8,98,65,'#101a30ed');rect(x-1,y-1,w+2,h+2,'#7c785c');rect(x,y,w,h,'#080e1d');if(!minimapColors[id])minimapColors[id]=Array.from({length:cols*rows},(_,i)=>minimapColor(id,(i%cols+.5)*m.cell,(Math.floor(i/cols)+.5)*m.cell));const cells=state.exploration?.[id]||'';for(let i=0;i<cells.length;i++)if(cells[i]==='1'){const gx=i%cols,gy=Math.floor(i/cols);rect(x+Math.floor(gx/cols*w),y+Math.floor(gy/rows*h),Math.max(1,Math.ceil((gx+1)/cols*w)-Math.floor(gx/cols*w)),Math.max(1,Math.ceil((gy+1)/rows*h)-Math.floor(gy/rows*h)),minimapColors[id][i])}const marker=(px,py,color)=>{if(exploredAt(id,px,py))rect(x+px/m.w*w-1,y+py/m.h*h-1,2,2,color)};if(id==='world'){marker(940,240,'#ffe18b');marker(150,650,'#c5d9bd');if(state.gateOpen||state.bellArrived)marker(1400,450,'#ffe18b');if(state.capitalKnown)marker(WORLD.capital.x,WORLD.capital.y,'#e8d6ff')}rect(x+p.x/m.w*w-1,y+p.y/m.h*h-1,3,3,'#fff3c5');ctx.fillStyle='#b6b29a';ctx.font=state.lang==='ar'?'8px Arial':'7px monospace';ctx.textAlign='center';ctx.fillText(tr('EXPLORED','المناطق المكتشفة'),455,70)}
// Smooth coastline polygons give every inlet a matching visual and physical edge.
function roundCoast(points){for(let pass=0;pass<2;pass++){const next=[];points.forEach((a,i)=>{const b=points[(i+1)%points.length];next.push([a[0]*.75+b[0]*.25,a[1]*.75+b[1]*.25],[a[0]*.25+b[0]*.75,a[1]*.25+b[1]*.75])});points=next}return points}
const MAIN_COAST=roundCoast([[92,580],[70,470],[126,390],[100,290],[205,225],[325,256],[420,191],[523,225],[650,185],[769,208],[876,147],[1005,158],[1076,215],[1195,244],[1300,207],[1395,242],[1459,302],[1420,344],[1542,395],[1576,490],[1520,561],[1441,568],[1478,668],[1381,741],[1251,711],[1224,818],[1097,912],[969,938],[900,889],[815,956],[716,983],[633,890],[522,909],[467,835],[365,862],[283,802],[196,824],[97,756],[92,669]]);
const CAPITAL_COAST=roundCoast([[1850,125],[1878,77],[1976,49],[2036,76],[2126,61],[2188,132],[2139,186],[2160,251],[2096,304],[2000,276],[1959,309],[1882,258],[1900,198],[1838,173]]);
