const WORLD_FORESTS=[[260,290,145,67],[768,354,150,62],[368,744,122,59],[1345,605,110,62],[991,823,108,62]];
function inPolygon(x,y,points){let inside=false;for(let i=0,j=points.length-1;i<points.length;j=i++){const a=points[i],b=points[j];if((a[1]>y)!==(b[1]>y)&&x<(b[0]-a[0])*(y-a[1])/(b[1]-a[1])+a[0])inside=!inside}return inside}
function mainLand(x,y){return inPolygon(x,y,MAIN_COAST)}
function capitalLand(x,y){return inPolygon(x,y,CAPITAL_COAST)}
function distanceToSegment(x,y,a,b){const dx=b[0]-a[0],dy=b[1]-a[1],t=Math.max(0,Math.min(1,((x-a[0])*dx+(y-a[1])*dy)/(dx*dx+dy*dy)));return Math.hypot(x-a[0]-t*dx,y-a[1]-t*dy)}
function riverAt(x,y){return WORLD_RIVER.some((a,i)=>i&&distanceToSegment(x,y,WORLD_RIVER[i-1],a)<9)}
function mountainAt(x,y){return WORLD.mountains.some(([bx,by,w,h])=>((x-bx-w/2)/(w/2+4))**2+((y-by-h/2)/(h/2+4))**2<1)}
function worldTerrain(x,y){const land=mainLand(x,y)||capitalLand(x,y);if(!land)return 'sea';if(((x-585)/105)**2+((y-426)/85)**2<1||riverAt(x,y))return 'water';if(mountainAt(x,y))return 'mountain';if(!mainLand(x-20,y)||!mainLand(x+20,y)||!mainLand(x,y-20)||!mainLand(x,y+20)){if(!capitalLand(x,y))return 'shore';if(!capitalLand(x-20,y)||!capitalLand(x+20,y)||!capitalLand(x,y-20)||!capitalLand(x,y+20))return 'shore'}if(WORLD_FORESTS.some(([cx,cy,rx,ry])=>((x-cx)/rx)**2+((y-cy)/ry)**2<1))return 'forest';if(((x-855)/190)**2+((y-532)/82)**2<1)return 'hills';return 'grass'}
const TERRAIN_COLORS={sea:['#264e73','#39678a'],water:['#305f85','#558dac'],shore:['#b5ad79','#9f9f70'],mountain:['#65716e','#7c8578'],forest:['#375d46','#426a4b'],hills:['#70835c','#61764f'],grass:['#547951','#476d4b']};
const WORLD_TILES=new Map();
function terrainTile(x,y){const tx=Math.floor(x/16),ty=Math.floor(y/16),key=ty*Math.ceil(WORLD.w/16)+tx;if(x<0||y<0||x>=WORLD.w||y>=WORLD.h)return 'sea';if(!WORLD_TILES.has(key))WORLD_TILES.set(key,worldTerrain(tx*16+8,ty*16+8));return WORLD_TILES.get(key)}
function walkableWorld(x,y){return mainLand(x,y)&&mainLand(x-4,y+8)&&mainLand(x+4,y+8)&&!['sea','water','mountain'].includes(terrainTile(x,y+7))}
