function ensureDevelopmentSandbox(){if(state.devTesting)return;developmentCheckpoint=checkpoint?copy(checkpoint):null;state.devTesting=true;state.explorationRun='dev-'+Date.now().toString(36)+'-'+(++explorationSequence);if(developmentCheckpoint)developmentCheckpoint.explorationRun=state.explorationRun}
function addDevelopmentGold(value){const amount=Number(value);if(!Number.isSafeInteger(amount)||amount<=0||amount>9999999){$('dev-gold-message').textContent=tr('Enter a whole amount from 1 to 9,999,999.','أدخل مبلغًا صحيحًا بين 1 و9,999,999.');return false}const gold=Math.min(9999999,state.gold+amount),added=gold-state.gold;if(!added){$('dev-gold-message').textContent=tr('Gold limit reached.','وصل الذهب إلى الحد الأقصى.');return false}ensureDevelopmentSandbox();state.gold=gold;if(developmentCheckpoint)developmentCheckpoint.gold=gold;$('dev-wallet').textContent=tr('Party gold: '+gold,'ذهب الفريق: '+gold);$('dev-gold-message').textContent=tr('Added '+added+' gold. Normal save preserved.','أُضيف '+added+' ذهبًا. بقي الحفظ العادي دون تغيير.');if(state.battle){updateStats();renderCommands()}if(state.market)renderMarket();return true}
function renderDevGold(){const area=$('dev-gold');area.replaceChildren();$('dev-gold-message').textContent='';const heading=document.createElement('h3');heading.textContent=tr('Add party gold','إضافة ذهب للفريق');area.appendChild(heading);const wallet=document.createElement('p');wallet.id='dev-wallet';wallet.textContent=tr('Party gold: '+state.gold,'ذهب الفريق: '+state.gold);area.appendChild(wallet);const shortcuts=document.createElement('div');shortcuts.className='dev-level-row';for(const value of [100,500,2000]){const button=document.createElement('button');button.type='button';button.className='small-button';button.textContent='+'+value;button.addEventListener('click',()=>addDevelopmentGold(value));shortcuts.appendChild(button)}area.appendChild(shortcuts);const row=document.createElement('div');row.className='dev-level-row';const label=document.createElement('label');label.textContent=tr('Amount','المبلغ');const input=document.createElement('input');input.id='dev-gold-amount';input.type='number';input.inputMode='numeric';input.min='1';input.max='9999999';input.step='1';input.value='200';label.appendChild(input);row.appendChild(label);const apply=document.createElement('button');apply.id='dev-gold-add';apply.type='button';apply.className='small-button';apply.textContent=tr('Add gold','أضف الذهب');apply.addEventListener('click',()=>addDevelopmentGold(input.value));input.addEventListener('keydown',e=>{e.stopPropagation();if(e.key==='Enter'){e.preventDefault();addDevelopmentGold(input.value)}});row.appendChild(apply);area.appendChild(row)}
