 if(!DEV_STAGES.some(group=>group.points.some(([id])=>id===stage)))return;developmentCheckpoint=null;state.exploration=emptyExploration();state.explorationLast={};state.explorationRun='dev-'+Date.now().toString(36)+'-'+(++explorationSequence);state.lastMovementAt=null;
 if(['pass','checkpointBattle'].includes(stage)){devStagePrevious('forest');const token=state.session;enterPass().then(()=>{if(token===state.session&&stage==='checkpointBattle'&&state.scene==='pass'&&state.mode==='map')confrontVarek()});return}
 if(['townInn','townForge','manorFoyer','manorStudy','manorGuest'].includes(stage)){devStagePrevious('town');if(stage.startsWith('manor')){state.chiefMet=stage==='manorGuest';setupManorRoom({manorFoyer:'foyer',manorStudy:'study',manorGuest:'guest'}[stage])}else setupInterior(stage==='townInn'?'inn':'forge');resumeChapterMap();return}
 if(stage==='venomJoined'){devStagePrevious('prison');recruitForTest();state.releaseRequested=false;setupTown();saveCheckpoint('town_resolved');resumeChapterMap();return}
