 if(['afterArena','stewardHall'].includes(stage)){devStagePrevious('bellhaven');state.arenaWins=3;state.michouState='recovering';state.captured=false;saveCheckpoint('before_abomination');if(stage==='stewardHall')setupMarchInterior('bellHall');resumeChapterMap();return}
 if(stage==='beforeNightRest'){devStagePrevious('abomination');state.nightRested=false;state.storyTime='day';setupMarchInterior('bellInn');saveCheckpoint('before_abomination');resumeChapterMap();return}
