// Part I finale: every witness has a different reason to help the voyage.
const AFTER_BELL_LINES={
 nia:[D('Nia','Last night I slept without leaving a candle for the next sacrifice. I had forgotten a morning could feel like this.','نمت الليلة الماضية دون أن أترك شمعة للأضحية التالية. كنت قد نسيت أن الصباح قد يحمل هذا الشعور.'),D('Nia','When you find the missing families, tell them their doors are still waiting. I will keep their houses ready.','حين تجدون العائلات المفقودة، أخبروهم أن أبواب بيوتهم ما زالت تنتظرهم. سأجهزها لعودتهم.')],
 mason:[D('Mason','I used to repair their cage wagons. Today I am repairing the harbor crane. I would rather help people leave standing.','كنت أصلح عرباتهم ذات الأقفاص. اليوم أصلح رافعة الميناء. أفضل أن أساعد الناس على المغادرة واقفين.'),D('Mason','Rook kept a seaworthy ship when the Brotherhood of Dawn ordered every fishing boat counted. Ask the old keeper by the south road.','احتفظ روك بسفينة صالحة للإبحار حين أمرت أخوية الفجر بإحصاء كل قارب صيد. اسألوا الحارس العجوز عند الطريق الجنوبي.')],
 courier:[D('Freed Courier','I copied the prisoner manifests. Your sister arrived at Valdorn six nights ago; her entry carries the citadel seal.','نسخت سجلات الأسرى. وصلت أختك إلى فالدور قبل ست ليالٍ؛ ويحمل قيدها ختم القلعة.'),D('Freed Courier','The patrols watch the northern channel. Give these charts to Captain Rook. He knows the reef passage they never use.','تراقب الدوريات القناة الشمالية. أعطوا هذه الخرائط للقبطان روك. يعرف ممر الشعاب الذي لا يستخدمونه أبدًا.')],
 sera:[D('Sergeant Sera','We guarded Malrec while our neighbors vanished. I cannot mend that by changing my badge.','حرسنا مالريك بينما كان جيراننا يختفون. لا أصلح ذلك بتغيير شارتي.'),D('Sergeant Sera','Four of my soldiers volunteered for your ship. We answer to Bellhaven now. Find Rook; I will meet you at the harbor.','تطوع أربعة من جنودي للذهاب معكم على السفينة. ولاؤنا الآن لبيلهافن. اعثروا على روك؛ سألتقيكم في الميناء.')],
 ivo:[D('Ivo','My brother was an offering. Malrec wrote his name beside a sack of flour in the ledger.','كان أخي أضحية. كتب مالريك اسمه بجانب كيس طحين في السجل.'),D('Ivo','I have no sword worth taking, but I can keep watch. I asked Sera to let me sail.','ليس لدي سيف يستحق حمله، لكنني أستطيع الحراسة. طلبت من سيرا أن تسمح لي بالإبحار.')],
 hallGuard:[D('Town Guard','Malrec will face the families here, not disappear into one of Raymond’s courts. We have sealed the shard away.','سيواجه مالريك العائلات هنا، ولن يختفي في إحدى محاكم ريموند. أغلقنا على الشظية في مكان آمن.'),D('Town Guard','Bring the captives home. We will hold this town while you cross the sea.','أعيدوا الأسرى إلى بيوتهم. سنحمي هذه المدينة بينما تعبرون البحر.')],
 prisoner:[D('Malrec','You took my shard. You did not take the voice that gave it to me.','أخذتم شظيتي. لم تأخذوا الصوت الذي منحني إياها.'),D('Malrec','Valdorn is not a village to be frightened into opening a door. Atrox will be waiting at its gates.','فالدور ليست قرية تُفتح أبوابها بمجرد إخافتها. سيكون أتروكس بانتظاركم عند بواباتها.')],
 inn:[D('Innkeeper Elin','I can put clean sheets on the beds again. No one is being marched out of this inn at dawn.','أستطيع وضع أغطية نظيفة على الأسرّة مجددًا. لن يُقتاد أحد من هذا النزل عند الفجر.'),D('Innkeeper Elin','Rest before the crossing. Twenty gold still feeds the staff and keeps the rooms warm.','استريحوا قبل العبور. ما زالت عشرون عملة تطعم العاملين وتبقي الغرف دافئة.')],
 gear:[D('Smith Oren','The soldiers brought me their old badges. I melted them into rivets for Rook’s ship. A better use for the metal.','أحضر الجنود شاراتهم القديمة. صهرتها إلى مسامير لسفينة روك. استخدام أفضل للمعدن.'),D('Smith Oren','Valdorn has armored ranks, not arena beasts. Fit your weapons and armor before you board.','في فالدور صفوف مدرعة، لا وحوش مدرّج. جهزوا أسلحتكم ودروعكم قبل الصعود.')],
 supplies:[D('Quartermaster Edda','I packed medicine for Sera’s volunteers. The sea is no place to discover an empty satchel.','حزمت الدواء لمتطوعي سيرا. البحر ليس مكانًا مناسبًا لاكتشاف حقيبة فارغة.'),D('Quartermaster Edda','Buy what you need before you leave. Health and mana both matter on the far shore.','اشتروا ما تحتاجونه قبل المغادرة. الصحة والمانا مهمتان على الشاطئ الآخر.')]
};
const HARBOR_LINES={
 captain:[D('Captain Rook','The Oathbound is ready. Once we leave this quay, our course is Valdorn. Make your last preparations.','سفينة العهد جاهزة. حين نغادر هذا الرصيف ستكون وجهتنا فالدور. أتموا استعداداتكم الأخيرة.')],
 sera:[D('Sergeant Sera','Those are volunteers on the deck, not prisoners. If Atrox sees our banner, he will know Bellhaven has chosen.','هؤلاء متطوعون على السطح، لا أسرى. حين يرى أتروكس رايتنا سيعرف أن بيلهافن اختارت.')],
 ivo:[D('Ivo','I have never seen the sea from the other side of a harbor wall. I am afraid. I am boarding anyway.','لم أرَ البحر من الجانب الآخر لسور الميناء قط. أنا خائف. سأصعد رغم ذلك.')],
 dockhand:[D('Dockhand Tamsin','I sealed the water casks and checked every rope. Bring the Oathbound back with more people than she carries out.','أغلقت براميل الماء وفحصت كل حبل. أعيدوا سفينة العهد ومعها أناس أكثر مما تحمل عند المغادرة.')]
};
async function talkCaptain(){const token=state.session;state.mode='cutscene';if(michouDecisionPending()){await say([
 D('Captain Rook','Someone asked for you. Michou is recovering in Mason’s house, south of the forge on the west side of town.','هناك شخص سأل عنكم. يتعافى ميشو في منزل ماسون، جنوب الحداد في الجهة الغربية من المدينة.'),
 D('Captain Rook','Mason showed him Malrec’s records. He wants to speak to you before you leave. Visit him, then come back and we will arrange the crossing.','أراه ماسون سجلات مالريك. يريد الحديث معكم قبل أن تغادروا. زوروه، ثم عودوا لنرتب عبور البحر.')
 ]);if(token!==state.session)return;state.michouVisitKnown=true;saveCheckpoint('bellhaven_freed');resumeChapterMap();return}if(!state.sailorMet){await say([D('Captain Rook','You knew me as the old keeper. Before the offerings, I was Rook, a sailor who knew every reef between here and Valdorn.','عرفتموني حارسًا عجوزًا. قبل الأضاحي كنت روك، بحارًا يعرف كل شعاب بين هنا وفالدور.'),D('Captain Rook','My boat survived their inspections. With Mason’s repairs, she is a ship again. I can take you to Valdorn, capital of the Brotherhood of Dawn.','نجا قاربي من تفتيشهم. وبإصلاحات ماسون عاد سفينةً. أستطيع أخذكم إلى فالدور، عاصمة أخوية الفجر.'),D('Venom','My sister is there. I am going.','أختي هناك. سأذهب.'),D('Captain Rook','Then we sail for the living. Sera and a few village soldiers have offered to join us.','إذًا نبحر من أجل الأحياء. عرضت سيرا وبعض جنود القرية مرافقتنا.'),D('Shadow','Show us the harbor.','أرِنا الميناء.')]);if(token!==state.session)return;state.sailorMet=true;state.harborUnlocked=true;saveCheckpoint('bellhaven_freed')}else await say(missionLines('The Oathbound is waiting at the harbor. I can lead you there when you are ready.','تنتظر سفينة العهد في الميناء. أستطيع قيادتكم إليها عندما تكونون جاهزين.','Captain Rook'));if(token!==state.session)return;const answer=await storyChoice('Follow Rook to the harbor?','هل تتبعون روك إلى الميناء؟',[['Follow the captain','اتبعوا القبطان','harbor'],['Prepare in town first','استعدوا في المدينة أولًا','later']],'Captain Rook');if(token!==state.session)return;if(answer==='harbor')await enterHarbor(true);else resumeChapterMap()}
function setupHarbor(){state.scene='harbor';state.camera={x:0,y:0};state.entities=partySprites(145,219);state.entities.push(entity('Captain Rook',230,194,'#8c818e',{harborTalk:'captain'}),entity('Sergeant Sera',200,127,'#8196a1',{harborTalk:'sera'}),entity('Ivo',124,137,'#898461',{harborTalk:'ivo'}),entity('Dockhand Tamsin',91,240,'#b38c68',{harborTalk:'dockhand'}));state.harborUnlocked=true}
function resumeHarbor(){state.mode='map';state.keys={};state.battle=null;state.trail=[];state.encounterDistance=0;ui.end.classList.add('hidden');ui.dialogue.classList.add('hidden');ui.battle.classList.add('hidden');ui.map.classList.remove('hidden');ui.objective.textContent=tr('BELLHAVEN HARBOR · PREPARE / BOARD THE OATHBOUND','ميناء بيلهافن · استعدوا / اصعدوا سفينة العهد');updatePrompt()}
async function enterHarbor(escort=false){const token=state.session;state.mode='cutscene';state.keys={};resetJoystick();ui.map.classList.add('hidden');if(escort){const captain=find('Captain Rook');if(captain)await moveTo(captain,416,468,2.7);if(token!==state.session)return;await Promise.all(state.party.map((h,i)=>moveTo(find(h.name),416-i*18,493,2.5)));if(token!==state.session)return}await fadeScene('harbor');if(token!==state.session)return;setupHarbor();saveCheckpoint('harbor_ready');await say([D('Sergeant Sera','The volunteers are aboard. Bellhaven’s own banner flies above them.','صعد المتطوعون. ترفرف راية بيلهافن نفسها فوقهم.'),D('Captain Rook','Last chance for beds, blades, and medicine. Step onto the gangplank when you are ready.','الفرصة الأخيرة للأسرّة والنصال والدواء. تقدموا إلى جسر الصعود حين تكونون جاهزين.')]);if(token===state.session)resumeHarbor()}
function harborPoint(){const p=state.player;if(!p)return null;if(Math.hypot(p.x-319,p.y-190)<28)return 'board';if(Math.hypot(p.x-24,p.y-208)<25)return 'town';return null}
async function boardOathbound(){if(michouDecisionPending()){await talkCaptain();return}const token=state.session;const choice=await storyChoice('Set sail for Valdorn?','هل تبحرون إلى فالدور؟',[['Set sail','أبحروا','sail'],['Prepare first','استعدوا أولًا','later']],'Captain Rook');if(token!==state.session)return;if(choice==='sail')await playPartOneFinale();else resumeHarbor()}
