function setPartOneEndCopy(){ui.end.classList.add('part-one-ending');$('end-kicker').textContent=tr('PART I COMPLETE · THE SEA BETWEEN US','اكتمل الجزء الأول · البحر بيننا');$('end-title').textContent=tr('SEE YOU IN PART II','إلى اللقاء في الجزء الثاني');$('end-epic').textContent=tr('THE GREAT EPIC','الملحمة الكبرى');$('end-epic').classList.remove('hidden');$('end-copy').textContent=tr('The Oathbound sails toward Valdorn. Atrox holds the gates. Behind the citadel walls, Raymond waits—and something unseen is listening.','تبحر سفينة العهد نحو فالدور. يحمي أتروكس البوابات. خلف جدران القلعة ينتظر ريموند، وشيء لا يُرى يصغي.');$('replay-finale').textContent=tr('Replay the finale','أعد مشاهدة الخاتمة');$('return-harbor').textContent=tr('Return to the harbor','عُد إلى الميناء');$('again').textContent=tr('New Game','لعبة جديدة');$('replay-finale').classList.remove('hidden');$('return-harbor').classList.remove('hidden')}
