async function playPartOneFinale(){if(state.finalePlaying)return;const token=state.session;state.finalePlaying=true;state.keys={};resetJoystick();ui.end.classList.add('hidden');saveCheckpoint('harbor_ready');await fadeScene('finale_voyage');if(token!==state.session)return;setFinaleScene('finale_voyage');startMusic('voyage');if(!await finalePause(token,1700))return;await say([D('Captain Rook','Cast off. Take the reef passage. The Oathbound sails for Valdorn.','فكوا الحبال. اسلكوا ممر الشعاب. تبحر سفينة العهد نحو فالدور.'),D('Sergeant Sera','Bellhaven’s soldiers stand with you. No cages. No offerings. Not again.','يقف جنود بيلهافن معكم. لا أقفاص. لا أضاحي. لن يحدث ذلك مجددًا.'),D('Venom','Six nights. Hold on a little longer, sister.','ست ليالٍ. اصمدي قليلًا بعد يا أختي.'),D('Astro','The sea is large. The citadel is larger than I would prefer. Our evidence is, fortunately, quite substantial.','البحر واسع. والقلعة أكبر مما كنت أفضّل. لكن أدلتنا، لحسن الحظ، قوية جدًا.'),D('Shadow','We bring them home.','سنعيدهم إلى بيوتهم.')]);if(token!==state.session)return;if(!await finalePause(token,1700))return;
 await fadeScene('raymond_private');if(token!==state.session)return;setFinaleScene('raymond_private',[entity('Raymond',272,147,colors.Raymond),entity('Messenger',179,146,'#84949c')]);startMusic('tension');await say([D('Messenger','Bellhaven has broken the seal, my commander. Malrec is imprisoned. A ship carries the witnesses, the marked swordsman, and soldiers under Bellhaven’s banner.','كسرت بيلهافن الختم يا قائدي. مالريك في السجن. تحمل سفينة الشهود والمبارز ذي العلامة وجنودًا تحت راية بيلهافن.'),D('Raymond','Summon Atrox. Leave the report. There will be no alarm in the square.','استدعِ أتروكس. اترك التقرير. لن يُعلن أي إنذار في الساحة.')]);if(token!==state.session)return;await moveTo(find('Messenger'),478,172,3.1);if(token!==state.session)return;state.entities=[find('Raymond')];await moveTo(find('Raymond'),304,138,2);if(token!==state.session)return;await say([D('Raymond','Malrec was nothing without what I gave him. They do not get to turn my dawn into their little legend.','لم يكن مالريك شيئًا دون ما منحته له. لن أسمح لهم أن يحوّلوا فجري إلى حكايتهم الصغيرة.'),D('Raymond','My lord... I kept the gates. I kept the key. Tell me they are still coming because you wanted them to.','يا سيدي... حافظت على البوابات. حافظت على المفتاح. قل لي إنهم ما زالوا قادمين لأنك أردت لهم ذلك.'),D('Narrator','The empty chamber gave him only the sound of his own breathing.','لم تمنحه الغرفة الخالية سوى صوت أنفاسه.'),D('Raymond','Then I will give them a city that kneels to no one but me.','إذًا سأمنحهم مدينة لا تركع إلا لي.')]);if(token!==state.session)return;
 await fadeScene('rally');if(token!==state.session)return;const crowd=Array.from({length:42},(_,i)=>entity('Citizen '+i,80+(i%9)*43,153+Math.floor(i/9)*23,['#698090','#917254','#7c8e68','#9b788b'][i%4])).filter(e=>Math.hypot(e.x-256,e.y-187)>32);setFinaleScene('rally',[entity('Raymond',256,105,colors.Raymond),...crowd]);startMusic('finale');await say([D('Raymond','People of Valdorn. Fear travels faster than any ship. Let us answer it with clear eyes.','يا أهل فالدور. يسافر الخوف أسرع من أي سفينة. فلنواجهه بأعين ثابتة.'),D('Raymond','A handful of armed agitators have brought unrest to Bellhaven. The Brotherhood of Dawn will protect its families and hear every grievance.','أثار عدد من المحرضين المسلحين اضطرابًا في بيلهافن. ستحمي أخوية الفجر عائلاتها وتسمع كل شكوى.'),D('Raymond','Your bread will reach your tables. Your children will sleep safely. Our gates stand because you built them together.','سيصل الخبز إلى موائدكم. سينام أطفالكم بأمان. بواباتنا صامدة لأنكم بنيتموها معًا.'),D('Citizen','One people! One dawn! No more chains!','شعب واحد! فجر واحد! لا قيود بعد اليوم!'),D('Raymond','Stand beside your neighbors. Trust the soldiers who defend you. No rumor will steal the future we have made.','قفوا إلى جانب جيرانكم. ثقوا بالجنود الذين يحمونكم. لن تسلبنا شائعة المستقبل الذي صنعناه.')]);if(token!==state.session)return;
 await fadeScene('finale_council');if(token!==state.session)return;setFinaleScene('finale_council',[entity('Raymond',281,132,colors.Raymond),entity('Atrox',161,142,colors.Atrox)]);await say([D('Raymond','Atrox. Reinforce the harbor chains and every city gate. Double the citadel watch. No one reaches the inner keep.','أتروكس. عزز سلاسل الميناء وكل بوابة للمدينة. ضاعف حراسة القلعة. لا يصل أحد إلى الحصن الداخلي.'),D('Atrox','I will command the outer gate myself. My legion will hold the line.','سأقود البوابة الخارجية بنفسي. سيصمد فيلقي.'),D('Raymond','Then make certain Valdorn remembers who protects it.','إذًا تأكد أن فالدور تتذكر من يحميها.'),D('Atrox','My soldiers will know their duty. The civilians stay behind us.','سيعرف جنودي واجبهم. يبقى المدنيون خلفنا.')]);if(token!==state.session)return;
 await fadeScene('finale_gate');if(token!==state.session)return;setFinaleScene('finale_gate');if(!await finalePause(token,1800))return;await say([D('Atrox','Shields to the front. Archers on the walls. Keep the harbor road clear for the wounded.','الدروع إلى المقدمة. الرماة على الأسوار. أبقوا طريق الميناء مفتوحًا للجرحى.'),D('Legion Captain','The Iron Legion stands ready, commander.','الفيلق الحديدي جاهز يا قائدي.'),D('Atrox','Then stand with me. Whatever comes through the sea, it meets us here.','إذًا قفوا معي. أيًا يكن القادم عبر البحر، سيواجهنا هنا.')]);if(token!==state.session)return;if(!await finalePause(token,1800))return;
 await fadeScene('finale_fortress');if(token!==state.session)return;setFinaleScene('finale_fortress');if(!await finalePause(token,2200))return;state.partOneComplete=true;state.finalePlaying=false;saveCheckpoint('part_one_complete');showPartOneEnd()
}
const partOnePrevious={reset,chapterObjective,updatePrompt,interact,blocked,update,draw,restoreCheckpoint,applyLanguage,developmentJump,chapterScene};
chapterScene=()=>['michouHouse','harbor','finale_voyage','finale_council','finale_gate','finale_fortress'].includes(state.scene)||partOnePrevious.chapterScene();
reset=function(){partOnePrevious.reset();state.finalePlaying=false;state.finaleStart=0;ui.end.classList.remove('part-one-ending');$('end-epic').classList.add('hidden');$('replay-finale').classList.add('hidden');$('return-harbor').classList.add('hidden')};
chapterObjective=function(){if(state.scene==='harbor'){ui.objective.textContent=tr('BELLHAVEN HARBOR · BOARD THE OATHBOUND','ميناء بيلهافن · اصعدوا سفينة العهد');return}if(['finale_voyage','finale_council','finale_gate','finale_fortress'].includes(state.scene)){ui.objective.textContent=tr('PART I FINALE · VALDORN AWAITS','خاتمة الجزء الأول · فالدور تنتظر');return}partOnePrevious.chapterObjective()};
blocked=function(x,y){if(state.scene==='harbor'){if(x<12||x>348||y<38||y+9>282)return true;if(x>247&&(y<172||y>205))return true;return footHitsRect(x,y,24,47,108,65)||footHitsRect(x,y,140,51,57,33)||actorsBlockFeet(x,y)}return partOnePrevious.blocked(x,y)};
updatePrompt=function(){if(state.scene!=='harbor'){partOnePrevious.updatePrompt();return}const npc=state.entities.find(e=>e.harborTalk&&e.visible&&Math.hypot(state.player.x-e.x,state.player.y-e.y)<34),point=harborPoint();state.harborNpc=npc;ui.prompt.classList.toggle('hidden',!npc&&!point);ui.prompt.textContent=npc?tr('A  Talk to '+npc.name,'A  تحدث مع '+({'Captain Rook':'القبطان روك','Sergeant Sera':'الرقيب سيرا','Ivo':'إيفو','Dockhand Tamsin':'تامسين'}[npc.name]||npc.name)):point==='board'?tr('A  Board the Oathbound','A  اصعدوا سفينة العهد'):tr('A  Return to Bellhaven','A  عودوا إلى بيلهافن')};
interact=function(){if(state.scene!=='harbor'||state.mode!=='map'){partOnePrevious.interact();return}updatePrompt();if(state.harborNpc){const token=state.session;state.mode='cutscene';say(HARBOR_LINES[state.harborNpc.harborTalk]).then(()=>{if(token===state.session)resumeHarbor()});return}const point=harborPoint();if(point==='board')boardOathbound();else if(point==='town'){setupBellhaven(416,488);resumeChapterMap()}};
update=function(){partOnePrevious.update()};
draw=function(){if(state.scene==='harbor'){state.time=performance.now();drawHarbor();requestAnimationFrame(draw);return}if(['finale_voyage','finale_council','finale_gate','finale_fortress'].includes(state.scene)){state.time=performance.now();if(state.scene==='finale_voyage')drawVoyage();else if(state.scene==='finale_council')drawFinaleCouncil();else if(state.scene==='finale_gate')drawArmyGate();else drawFortressVista();requestAnimationFrame(draw);return}partOnePrevious.draw()};
restoreCheckpoint=function(){const saved=state.devTesting?developmentCheckpoint:(checkpoint||readStoredCheckpoint());if(!validCheckpoint(saved))return false;const restored=partOnePrevious.restoreCheckpoint();if(!restored)return false;if(saved.id==='harbor_ready'){setupHarbor();resumeHarbor()}else if(saved.id==='part_one_complete')showPartOneEnd();return true};
applyLanguage=function(){partOnePrevious.applyLanguage();if(state.mode==='end'&&state.partOneComplete)setPartOneEndCopy()};
const normalMusicStep=musicStep;
musicStep=function(){if(!['voyage','finale'].includes(audio.mode)){normalMusicStep();return}if(!audio.on||!audio.ctx||audio.ctx.state!=='running')return;const melody=audio.mode==='voyage'?[146.83,196,220,293.66,261.63,220,196,174.61]:[146.83,146.83,220,174.61,196,146.83,130.81,110],i=audio.step++%8;tone(melody[i],.63,'triangle',.25,audio.musicGain);if(i%2===0)tone(melody[i]/2,.8,'sine',.15,audio.musicGain);if(i%4===0){tone(melody[i]*1.5,.8,'triangle',.11,audio.musicGain);tone(melody[i]*2,.45,'square',.08,audio.musicGain,.05)}};
DEV_STAGES.push({label:['Part I ending','خاتمة الجزء الأول'],points:[['harbor','Harbor / boarding preparations','الميناء / الاستعداد للإبحار'],['partFinale','Full finale / voyage and army','الخاتمة كاملة / السفينة والجيش'],['partEnd','Part I / final screen','الجزء الأول / شاشة النهاية']]});
