$('replay-finale').addEventListener('click',()=>{state.partOneComplete=false;state.finalePlaying=false;playPartOneFinale()});$('return-harbor').addEventListener('click',()=>{state.partOneComplete=false;setupHarbor();saveCheckpoint('harbor_ready');resumeHarbor();startMusic('village')});

